import { Component, computed, input } from '@angular/core';
import { NzButtonModule, NzButtonSize, NzButtonShape } from 'ng-zorro-antd/button';

export type HrmButtonVariant = 'primary' | 'default' | 'dashed' | 'text' | 'link';
export type HrmButtonSize = 'sm' | 'md' | 'lg';
export type HrmButtonShape = 'default' | 'round' | 'circle';

/** hrm-button — bọc nz-button, API sạch (variant/size), theme bằng design token.
 *  Dùng: <hrm-button variant="primary" size="md">Lưu</hrm-button>
 *  Icon-only (chỉ biểu tượng) BẮT BUỘC có ariaLabel cho screen-reader:
 *  <hrm-button [iconOnly]="true" ariaLabel="Xoá"><tabler-icon [icon]="IconTrash" /></hrm-button> */
@Component({
  selector: 'hrm-button',
  imports: [NzButtonModule],
  template: `
    <button
      nz-button
      [nzType]="variant()"
      [nzSize]="nzSize()"
      [nzDanger]="danger()"
      [nzLoading]="loading()"
      [nzBlock]="block()"
      [nzShape]="nzShape()"
      [disabled]="disabled()"
      [class.hrm-btn-icon-only]="iconOnly()"
      [attr.aria-label]="ariaLabel() || null"
      [attr.type]="htmlType()">
      <ng-content />
    </button>
  `,
  host: { class: 'hrm-button' },
})
export class HrmButton {
  readonly variant = input<HrmButtonVariant>('default');
  readonly size = input<HrmButtonSize>('md');
  readonly shape = input<HrmButtonShape>('default');
  readonly danger = input(false);
  readonly loading = input(false);
  readonly block = input(false);
  readonly disabled = input(false);
  /** Nút chỉ có biểu tượng (vuông) — nhớ set ariaLabel. */
  readonly iconOnly = input(false);
  /** Nhãn cho screen-reader (bắt buộc khi iconOnly). */
  readonly ariaLabel = input('');
  readonly htmlType = input<'button' | 'submit' | 'reset'>('button');

  protected readonly nzSize = computed<NzButtonSize>(() =>
    this.size() === 'sm' ? 'small' : this.size() === 'lg' ? 'large' : 'default');
  protected readonly nzShape = computed<NzButtonShape>(() =>
    this.shape() === 'default' ? null : (this.shape() as NzButtonShape));
}
